import{_ as e,o as l,c as g,a5 as o}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"多模块Maven项目","description":"","frontmatter":{"title":"多模块Maven项目","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/多模块Maven项目/多模块Maven项目.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/多模块Maven项目/多模块Maven项目.md"}'),n={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/多模块Maven项目/多模块Maven项目.md"};function r(i,t,a,p,s,d){return l(),g("div",null,[...t[0]||(t[0]=[o('<div><p>多模块Maven项目。您的主要应用可能是在ms-admin模块中，因为它的名称和其包含的资源文件（如application.yml、logback.xml等）都暗示它可能是主应用模块。</p><p>一、顶级容器pom.xml；</p><ul><li>它没有parent节点：正确。顶级容器pom.xml通常不会有parent节点，因为它是整个多模块项目的根。</li><li>它有modules表明它包括哪些模块：正确。在顶级容器中使用modules元素来列出所有子模块。</li><li>虽然子模块在物理结构上被包括在主模块中，并在主模块的modules元素中被声明，但如果一个子模块想要使用另一个子模块的类或资源，它仍然需要在其pom.xml文件中明确地添加该子模块的依赖声明。</li><li>它的类型为：&lt;packaging&gt;pom&lt;/packaging&gt;：正确。顶级容器pom.xml的packaging类型应为pom，这表示它主要用于聚合和管理子模块，而不是产生特定的构建输出。</li></ul><p>这个pom.xml文件是一个多模块Maven项目的主pom文件，它定义了一些常用的属性、依赖管理和模块。从你提供的内容来看，这个配置大致是合理的，但仍有一些需要注意的点：</p><ol><li>groupId与artifactId的使用 <ul><li>通常在多模块项目中，每个模块的groupId应该是相同的，而artifactId则应该是各自不同的，用来标识各个模块。从你给出的pom.xml来看，各模块的artifactId都是不同的，这是正确的。</li></ul></li><li>version属性的使用 <ul><li>通常情况下，主模块的版本号和子模块的版本号应该保持一致。在你给的pom.xml中，所有模块的版本号都是从&lt;ms.version&gt;1.0.0&lt;/ms.version&gt;属性中获取的，这是一个好做法。</li></ul></li><li>&lt;packaging&gt;pom&lt;/packaging&gt; <ul><li>这是正确的，因为这是一个聚合模块，所以其包类型应该是pom。</li></ul></li><li>依赖管理 (dependencyManagement) <ul><li>在主pom文件中使用&lt;dependencyManagement&gt;元素来定义子模块通用的依赖是一个好做法。这样可以保证子模块使用相同的依赖版本，便于统一管理。</li></ul></li><li>&lt;repositories&gt; 和 &lt;pluginRepositories&gt; <ul><li>你在这里指定了阿里云的Maven仓库，这对于中国的开发者来说是一个加速下载依赖的好做法，但如果项目需要在其他地区部署，可能会遇到访问速度的问题。</li></ul></li><li>模块的声明 <ul><li>ms-admin被声明为一个模块，但在依赖管理中并没有看到它的依赖声明。确保其他模块如果需要依赖ms-admin，则需要在它们自己的pom.xml文件中添加依赖声明。</li></ul></li><li>潜在的问题 <ul><li>&lt;groupId&gt;com.alibaba.fastjson2&lt;/groupId&gt;，这里的fastjson2可能是个错误。通常，fastjson的groupId是com.alibaba，artifactId是fastjson。你需要验证是否真的需要使用fastjson2。</li></ul></li></ol><p>调整建议：</p><ol start="9"><li>对于每个模块，除非它确实需要某个依赖，否则不应在其pom.xml文件中直接引入从dependencyManagement中定义的依赖。这样可以避免不必要的依赖传递。</li><li>根据实际情况检查fastjson的依赖声明。</li><li>考虑为常用的插件版本也定义属性，例如，你已经为maven-compiler-plugin定义了版本3.1，你可以为它定义一个属性，类似于你为依赖定义的版本属性。</li><li>最后，建议经常运行mvn clean install或mvn clean verify来确保所有的模块都能正确编译和安装。</li></ol><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;project xmlns=&quot;<a href="http://maven.apache.org/POM/4.0.0" target="_blank" rel="noreferrer">http://maven.apache.org/POM/4.0.0</a>&quot; xmlns:xsi=&quot;<a href="http://www.w3.org/2001/XMLSchema-instance" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema-instance</a>&quot; xsi:schemaLocation=&quot;<a href="http://maven.apache.org/POM/4.0.0" target="_blank" rel="noreferrer">http://maven.apache.org/POM/4.0.0</a> <a href="http://maven.apache.org/xsd/maven-4.0.0.xsd" target="_blank" rel="noreferrer">http://maven.apache.org/xsd/maven-4.0.0.xsd</a>&quot;&gt; &lt;modelVersion&gt;4.0.0&lt;/modelVersion&gt;</p><p>&lt;groupId&gt;com.ms&lt;/groupId&gt; &lt;artifactId&gt;ms&lt;/artifactId&gt; &lt;version&gt;1.0.0&lt;/version&gt;</p><p>&lt;name&gt;ms&lt;/name&gt; &lt;description&gt;民晟管理系统&lt;/description&gt; &lt;properties&gt; &lt;ms.version&gt;1.0.0&lt;/ms.version&gt; &lt;project.build.sourceEncoding&gt;UTF-8&lt;/project.build.sourceEncoding&gt; &lt;project.reporting.outputEncoding&gt;UTF-8&lt;/project.reporting.outputEncoding&gt; &lt;java.version&gt;1.8&lt;/java.version&gt; &lt;maven-jar-plugin.version&gt;3.1.1&lt;/maven-jar-plugin.version&gt; &lt;druid.version&gt;1.2.14&lt;/druid.version&gt; &lt;bitwalker.version&gt;1.21&lt;/bitwalker.version&gt; &lt;swagger.version&gt;3.0.0&lt;/swagger.version&gt; &lt;kaptcha.version&gt;2.3.2&lt;/kaptcha.version&gt; &lt;mybatis-spring-boot.version&gt;2.2.2&lt;/mybatis-spring-boot.version&gt; &lt;pagehelper.boot.version&gt;1.4.5&lt;/pagehelper.boot.version&gt; &lt;fastjson.version&gt;2.0.16&lt;/fastjson.version&gt; &lt;oshi.version&gt;6.3.2&lt;/oshi.version&gt; &lt;commons.io.version&gt;2.11.0&lt;/commons.io.version&gt; &lt;commons.fileupload.version&gt;1.4&lt;/commons.fileupload.version&gt; &lt;commons.collections.version&gt;3.2.2&lt;/commons.collections.version&gt; &lt;poi.version&gt;4.1.2&lt;/poi.version&gt; &lt;velocity.version&gt;2.3&lt;/velocity.version&gt; &lt;jwt.version&gt;0.9.1&lt;/jwt.version&gt; &lt;/properties&gt;</p><p>&lt;!-- 依赖声明 --&gt; &lt;dependencyManagement&gt; &lt;dependencies&gt;</p><p>&lt;!-- SpringBoot的依赖配置--&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-dependencies&lt;/artifactId&gt; &lt;version&gt;2.5.14&lt;/version&gt; &lt;type&gt;pom&lt;/type&gt; &lt;scope&gt;import&lt;/scope&gt; &lt;/dependency&gt;</p><p>&lt;!-- 阿里数据库连接池 --&gt; &lt;dependency&gt; &lt;groupId&gt;com.alibaba&lt;/groupId&gt; &lt;artifactId&gt;druid-spring-boot-starter&lt;/artifactId&gt; &lt;version&gt;${druid.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 解析客户端操作系统、浏览器等 --&gt; &lt;dependency&gt; &lt;groupId&gt;eu.bitwalker&lt;/groupId&gt; &lt;artifactId&gt;UserAgentUtils&lt;/artifactId&gt; &lt;version&gt;${bitwalker.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- SpringBoot集成mybatis框架 --&gt; &lt;dependency&gt; &lt;groupId&gt;org.mybatis.spring.boot&lt;/groupId&gt; &lt;artifactId&gt;mybatis-spring-boot-starter&lt;/artifactId&gt; &lt;version&gt;${mybatis-spring-boot.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- pagehelper 分页插件 --&gt; &lt;dependency&gt; &lt;groupId&gt;com.github.pagehelper&lt;/groupId&gt; &lt;artifactId&gt;pagehelper-spring-boot-starter&lt;/artifactId&gt; &lt;version&gt;${pagehelper.boot.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 获取系统信息 --&gt; &lt;dependency&gt; &lt;groupId&gt;com.github.oshi&lt;/groupId&gt; &lt;artifactId&gt;oshi-core&lt;/artifactId&gt; &lt;version&gt;${oshi.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- Swagger3依赖 --&gt; &lt;dependency&gt; &lt;groupId&gt;io.springfox&lt;/groupId&gt; &lt;artifactId&gt;springfox-boot-starter&lt;/artifactId&gt; &lt;version&gt;${swagger.version}&lt;/version&gt; &lt;exclusions&gt; &lt;exclusion&gt; &lt;groupId&gt;io.swagger&lt;/groupId&gt; &lt;artifactId&gt;swagger-models&lt;/artifactId&gt; &lt;/exclusion&gt; &lt;/exclusions&gt; &lt;/dependency&gt;</p><p>&lt;!-- io常用工具类 --&gt; &lt;dependency&gt; &lt;groupId&gt;commons-io&lt;/groupId&gt; &lt;artifactId&gt;commons-io&lt;/artifactId&gt; &lt;version&gt;${commons.io.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 文件上传工具类 --&gt; &lt;dependency&gt; &lt;groupId&gt;commons-fileupload&lt;/groupId&gt; &lt;artifactId&gt;commons-fileupload&lt;/artifactId&gt; &lt;version&gt;${commons.fileupload.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- excel工具 --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.poi&lt;/groupId&gt; &lt;artifactId&gt;poi-ooxml&lt;/artifactId&gt; &lt;version&gt;${poi.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- velocity代码生成使用模板 --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.velocity&lt;/groupId&gt; &lt;artifactId&gt;velocity-engine-core&lt;/artifactId&gt; &lt;version&gt;${velocity.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- collections工具类 --&gt; &lt;dependency&gt; &lt;groupId&gt;commons-collections&lt;/groupId&gt; &lt;artifactId&gt;commons-collections&lt;/artifactId&gt; &lt;version&gt;${commons.collections.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 阿里JSON解析器 --&gt; &lt;dependency&gt; &lt;groupId&gt;com.alibaba.fastjson2&lt;/groupId&gt; &lt;artifactId&gt;fastjson2&lt;/artifactId&gt; &lt;version&gt;${fastjson.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- Token生成与解析--&gt; &lt;dependency&gt; &lt;groupId&gt;io.jsonwebtoken&lt;/groupId&gt; &lt;artifactId&gt;jjwt&lt;/artifactId&gt; &lt;version&gt;${jwt.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 验证码 --&gt; &lt;dependency&gt; &lt;groupId&gt;com.github.penggle&lt;/groupId&gt; &lt;artifactId&gt;kaptcha&lt;/artifactId&gt; &lt;version&gt;${kaptcha.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 定时任务--&gt; &lt;dependency&gt; &lt;groupId&gt;com.ms&lt;/groupId&gt; &lt;artifactId&gt;ms-quartz&lt;/artifactId&gt; &lt;version&gt;${ms.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 代码生成--&gt; &lt;dependency&gt; &lt;groupId&gt;com.ms&lt;/groupId&gt; &lt;artifactId&gt;ms-generator&lt;/artifactId&gt; &lt;version&gt;${ms.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 核心模块--&gt; &lt;dependency&gt; &lt;groupId&gt;com.ms&lt;/groupId&gt; &lt;artifactId&gt;ms-framework&lt;/artifactId&gt; &lt;version&gt;${ms.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 系统模块--&gt; &lt;dependency&gt; &lt;groupId&gt;com.ms&lt;/groupId&gt; &lt;artifactId&gt;ms-system&lt;/artifactId&gt; &lt;version&gt;${ms.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;!-- 通用工具--&gt; &lt;dependency&gt; &lt;groupId&gt;com.ms&lt;/groupId&gt; &lt;artifactId&gt;ms-common&lt;/artifactId&gt; &lt;version&gt;${ms.version}&lt;/version&gt; &lt;/dependency&gt;</p><p>&lt;/dependencies&gt; &lt;/dependencyManagement&gt;</p><p>==&lt;modules&gt;== ==&lt;module&gt;ms-admin&lt;/module&gt;== ==&lt;module&gt;ms-framework&lt;/module&gt;== ==&lt;module&gt;ms-system&lt;/module&gt;== ==&lt;module&gt;ms-quartz&lt;/module&gt;== ==&lt;module&gt;ms-generator&lt;/module&gt;== ==&lt;module&gt;ms-common&lt;/module&gt;== ==&lt;/modules&gt;== ==&lt;packaging&gt;pom&lt;/packaging&gt;==</p><p>&lt;dependencies&gt;</p><p>&lt;/dependencies&gt;</p><p>&lt;build&gt; &lt;plugins&gt; &lt;plugin&gt; &lt;groupId&gt;org.apache.maven.plugins&lt;/groupId&gt; &lt;artifactId&gt;maven-compiler-plugin&lt;/artifactId&gt; &lt;version&gt;3.1&lt;/version&gt; &lt;configuration&gt; &lt;source&gt;${java.version}&lt;/source&gt; &lt;target&gt;${java.version}&lt;/target&gt; &lt;encoding&gt;${project.build.sourceEncoding}&lt;/encoding&gt; &lt;/configuration&gt; &lt;/plugin&gt; &lt;/plugins&gt; &lt;/build&gt;</p><p>&lt;repositories&gt; &lt;repository&gt; &lt;id&gt;public&lt;/id&gt; &lt;name&gt;aliyun nexus&lt;/name&gt; &lt;url&gt;<a href="https://maven.aliyun.com/repository/public%5C" target="_blank" rel="noreferrer">https://maven.aliyun.com/repository/public\\</a>&lt;/url&gt; &lt;releases&gt; &lt;enabled&gt;true&lt;/enabled&gt; &lt;/releases&gt; &lt;/repository&gt; &lt;/repositories&gt;</p><p>&lt;pluginRepositories&gt; &lt;pluginRepository&gt; &lt;id&gt;public&lt;/id&gt; &lt;name&gt;aliyun nexus&lt;/name&gt; &lt;url&gt;<a href="https://maven.aliyun.com/repository/public%5C" target="_blank" rel="noreferrer">https://maven.aliyun.com/repository/public\\</a>&lt;/url&gt; &lt;releases&gt; &lt;enabled&gt;true&lt;/enabled&gt; &lt;/releases&gt; &lt;snapshots&gt; &lt;enabled&gt;false&lt;/enabled&gt; &lt;/snapshots&gt; &lt;/pluginRepository&gt; &lt;/pluginRepositories&gt;</p><p>&lt;/project&gt;</p></div>',1)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
